 * all listed in account.inputFields, and pass them in here. This function will
 * insert them in the fields, returning a fully filled-out account ready to be
 * created.
 *
 * @param {AccountConfig} account - The account data to be modified. It may or
 *   may not contain placeholders.
 *   After this function, it should not contain placeholders anymore.
 *   This object will be modified in-place.
 * @param {string} realname - Real name of user, as will appear in From of
 *   outgoing messages
 * @param {string} emailfull - Full email address of this account,
 *   e.g. "joe@example.com".
 *   Empty of incomplete email addresses will/may be rejected.
 * @param {string} password - The password for the incoming server and
 *   (if necessary) the outgoing server.
 */
AccountConfig.replaceVariables = function (
  account,
  realname,
  emailfull,
  password
) {
  lazy.InputSanitizer.nonemptystring(emailfull);
  const emailsplit = emailfull.split("@");
  lazy.AccountCreationUtils.assert(
    emailsplit.length == 2,
    "email address not in expected format: must contain exactly one @"
  );
  const emaillocal = lazy.InputSanitizer.nonemptystring(emailsplit[0]);
  const emaildomain = lazy.InputSanitizer.hostname(emailsplit[1]);
  lazy.InputSanitizer.label(realname);
  lazy.InputSanitizer.nonemptystring(realname);

  const otherVariables = {};
  otherVariables.EMAILADDRESS = emailfull;
  otherVariables.EMAILLOCALPART = emaillocal;
  otherVariables.EMAILDOMAIN = emaildomain;
  otherVariables.REALNAME = realname;

  _replaceConfig({ config: account.incoming, otherVariables, password });
  _replaceConfig({ config: account.outgoing, otherVariables, password });

  for (const alternative of account.incomingAlternatives) {
    _replaceConfig({ config: alternative, otherVariables, password });
  }

  account.identity.realname = _replaceVariable(
    account.identity.realname,
    otherVariables
  );
  account.identity.emailAddress = _replaceVariable(
    account.identity.emailAddress,
    otherVariables
  );
  account.displayName = _replaceVariable(account.displayName, otherVariables);
};

function _replaceConfig({ config, otherVariables, password }) {
  if (password) {
    config.password = password;
  }
  config.username = _replaceVariable(config.username, otherVariables);
  if (config.hostname) {
    config.hostname = _replaceVariable(config.hostname, otherVariables);
  }
}

function _replaceVariable(variable, values) {
  let str = variable;
  if (typeof str != "string") {
    return str;
  }

  for (const varname in values) {
    str = str.replaceAll("%" + varname + "%", values[varname]);
  }

  return str;
}
